/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 6 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , cast(null as varchar) as NATURAL_ADDITION_RULE_INDICATOR
        , cast(null as varchar) as NATURAL_ADDITION_NEWBORN_DAYS
        , cast(null as varchar) as NATURAL_ADDITION_SPOUSE_DAYS
        , MEM_DATA_BULK_UPLOAD as MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR
        , MEMBER_DOB_YN as DOB_VALIDATION_RULE
        , MEM_BACKDATE_LIMIT as MEMBER_BACKDATING_LIMIT_DAYS
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NATURAL_ADDITION_RULE_INDICATOR end) as NATURAL_ADDITION_RULE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NATURAL_ADDITION_NEWBORN_DAYS end) as NATURAL_ADDITION_NEWBORN_DAYS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NATURAL_ADDITION_SPOUSE_DAYS end) as NATURAL_ADDITION_SPOUSE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR end) as MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then DOB_VALIDATION_RULE end) as DOB_VALIDATION_RULE,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_BACKDATING_LIMIT_DAYS end) as MEMBER_BACKDATING_LIMIT_DAYS,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when NATURAL_ADDITION_RULE_INDICATOR is not null or NATURAL_ADDITION_NEWBORN_DAYS is not null or NATURAL_ADDITION_SPOUSE_DAYS is not null or MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR is not null or DOB_VALIDATION_RULE is not null or MEMBER_BACKDATING_LIMIT_DAYS is not null
                     then md5(upper(coalesce(cast(NATURAL_ADDITION_RULE_INDICATOR as varchar), '') || '|' || coalesce(cast(NATURAL_ADDITION_NEWBORN_DAYS as varchar), '') || '|' || coalesce(cast(NATURAL_ADDITION_SPOUSE_DAYS as varchar), '') || '|' || coalesce(cast(MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(DOB_VALIDATION_RULE as varchar), '') || '|' || coalesce(cast(MEMBER_BACKDATING_LIMIT_DAYS as varchar), '')))
                end as SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF is not null
